257	/**
258	 * A sheet's settings: its clerk limit (null: no limit), its floor (a claim's live due is at least it), its terms
259	 * (a claim is due by its date plus this many days), the terms set for each grade that has its own (by grade; any
260	 * other grade uses the sheet's terms), its late percent (an overdue claim gains it of its figure
261	 * every full 30 days), its rounding policy date (null: blank, the sheet's
262	 * today), its period numbering from date (null: off; on or after it, an opened claim is numbered within its period)
263	 * its cap (null: none; a person's due-total is at most it), its proof threshold (null: none; a claim whose due is above
264	 * the one in force on its date is settled or approved only once it has a proof) the roles given to user names (any other name is a clerk) and its
265	 * permission matrix (the roles allowed each of open, settle, void, reassign, close and reopen) and its grace days (null: off;
266	 * when its today is changed, an open period whose to-date plus them is before the new today is closed).
267	 * The clerk limit, floor, terms, grade terms, late percent, cap and proof threshold are those in force on the sheet's today; {@code dated}
268	 * holds every value recorded for them, by from-date. {@code delegations} are the steward role delegated to user names, in the
269	 * order made; one in force on {@code today} (the sheet's today) makes its user act as a steward in every rule.
270	 */
271	public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms, Map<String, Integer> gradeTerms, BigDecimal latePct,
272	        LocalDate policyDate, LocalDate periodNumberingFrom, BigDecimal cap, BigDecimal proofThreshold, List<UserRole> roles, DatedSettings dated, Permissions permissions, Integer graceDays,
273	        LocalDate today, List<Delegation> delegations) {
274	
275	    /** The role the user name acts in: steward while a delegation to it is in force on today, else its given role. */
276	    public Role roleOf(String user) {
277	        return delegatorOf(user) != null ? Role.STEWARD : givenRoleOf(user);
278	    }
279	
280	    /** The role given to the user name, else clerk (a delegation aside). */
281	    public Role givenRoleOf(String user) {
282	        return roles.stream().filter((r) -> r.user().equals(user)).map(UserRole::role).findFirst().orElse(Role.CLERK);
283	    }
284	
285	    /** The steward who delegated the role to the user name by the latest delegation in force on today, else null. */
286	    public String delegatorOf(String user) {
287	        String by = null;
288	        for (Delegation d : delegations) {
289	            if (d.user().equals(user) && d.covers(today)) {
290	                by = d.by();
291	            }
292	        }
293	        return by;
294	    }
295	
296	    /** Whether the user's role is allowed the action (open, settle, void, reassign, close or reopen) by the permission matrix. */
297	    public boolean may(String user, String action) {
298	        return permissions.allows(action, roleOf(user));
299	    }
300	
301	    /** Whether the user may settle a claim with this due (null: n/a, within any limit). */
302	    public boolean maySettle(String user, BigDecimal due) {
303	        return roleOf(user) == Role.STEWARD || clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
304	    }
