318	
319	public class ValidateSettingsRequest {
320	
321	    /** 0.00 or more, with at most two decimals. */
322	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,13}(\\.\\d{1,2})?|\\.\\d{1,2}");
323	
324	    /** A percent: 0.00 or more, with at most two decimals. */
325	    private static final Pattern PERCENT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?|\\.\\d{1,2}");
326	
327	    /** The grades terms can be set for. */
328	    private static final Set<String> GRADES = Set.of("A", "B", "C");
329	
330	    /** 0 or more whole days. */
331	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
332	
333	    public void validate(@RequestBody @Valid SettingsRequest request, Out<ClerkLimit> limit, Out<Floor> floor,
334	            Out<Terms> terms, Out<LatePct> latePct, Out<PolicyDate> policyDate,
335	            Out<PeriodNumberingFrom> periodNumberingFrom, Out<GradeTerms> gradeTerms, Out<Cap> cap,
336	            Out<ProofThreshold> proofThreshold, Out<PermissionChanges> permissions, Out<GraceDays> graceDays)
337	            throws InvalidSettingException {
338	        limit.set(clerkLimit(request.clerkLimit(), from(request.clerkLimitFrom(), "clerk limit")));
339	        floor.set(floor(request.floor(), from(request.floorFrom(), "floor")));
340	        terms.set(terms(request.terms(), from(request.termsFrom(), "terms")));
341	        latePct.set(latePct(request.latePct(), from(request.latePctFrom(), "late percent")));
342	        policyDate.set(policyDate(request.policyDate()));
343	        periodNumberingFrom.set(periodNumberingFrom(request.periodNumberingFrom()));
344	        gradeTerms.set(gradeTerms(request.gradeTerms(), request.gradeTermsFrom()));
345	        cap.set(cap(request.cap(), from(request.capFrom(), "cap")));
346	        proofThreshold.set(proofThreshold(request.proofThreshold(), from(request.proofThresholdFrom(), "proof threshold")));
347	        permissions.set(permissions(request.permissions()));
348	        graceDays.set(graceDays(request.graceDays()));
349	    }
350	
351	    /** A from-date typed with a setting (null: left out or blank, the sheet's today). */
352	    private static LocalDate from(String requested, String what) throws InvalidSettingException {
353	        String value = requested == null ? "" : requested.trim();
354	        if (value.isEmpty()) {
355	            return null;
356	        }
357	        try {
358	            return LocalDate.parse(value);
359	        } catch (DateTimeParseException e) {
360	            throw new InvalidSettingException("The " + what + " from-date must be a date (yyyy-MM-dd), or blank.");
361	        }
362	    }
363	
364	    private static PermissionChanges permissions(Map<String, String> requested) throws InvalidSettingException {
365	        Map<String, String> entries = new LinkedHashMap<>();
366	        if (requested == null) {
367	            return new PermissionChanges(entries);
368	        }
369	        for (String action : requested.keySet()) {
370	            if (!Permissions.ACTIONS.contains(action)) {
371	                throw new InvalidSettingException("Permissions can only be set for open, settle, void, reassign, close or reopen.");
372	            }
373	        }
374	        for (String action : Permissions.ACTIONS) {
375	            if (!requested.containsKey(action)) {
376	                continue;
377	            }
378	            String value = requested.get(action) == null ? "" : requested.get(action).trim();
379	            if (value.isEmpty()) {
380	                entries.put(action, "");
381	            } else if (Permissions.parse(value) == null) {
382	                throw new InvalidSettingException("The roles for " + action + " must be clerk or steward, comma separated, or blank.");
383	            } else {
384	                entries.put(action, Permissions.label(value));
385	            }
386	        }
387	        return new PermissionChanges(entries);
388	    }
389	
390	    private static GraceDays graceDays(String requested) throws InvalidSettingException {
391	        if (requested == null) {
392	            return new GraceDays(false, null);
393	        }
394	        String value = requested.trim();
395	        if (value.isEmpty()) {
396	            return new GraceDays(true, null);
397	        }
398	        if (!DAYS.matcher(value).matches()) {
399	            throw new InvalidSettingException("The grace days must be a whole number of days, 0 or more, or blank.");
400	        }
401	        return new GraceDays(true, Integer.parseInt(value));
402	    }
403	
404	    private static Cap cap(String requested, LocalDate from) throws InvalidSettingException {
405	        if (requested == null) {
406	            return new Cap(false, null, null);
407	        }
408	        String value = requested.trim();
409	        if (value.isEmpty()) {
410	            return new Cap(true, null, from);
411	        }
412	        if (!AMOUNT.matcher(value).matches()) {
413	            throw new InvalidSettingException("The cap must be 0.00 or more, with at most two decimals, or blank.");
414	        }
415	        return new Cap(true, new BigDecimal(value).setScale(2), from);
416	    }
417	
418	    private static ProofThreshold proofThreshold(String requested, LocalDate from) throws InvalidSettingException {
419	        if (requested == null) {
420	            return new ProofThreshold(false, null, null);
421	        }
422	        String value = requested.trim();
423	        if (value.isEmpty()) {
424	            return new ProofThreshold(true, null, from);
425	        }
426	        if (!AMOUNT.matcher(value).matches()) {
427	            throw new InvalidSettingException("The proof threshold must be 0.00 or more, with at most two decimals, or blank.");
428	        }
429	        return new ProofThreshold(true, new BigDecimal(value).setScale(2), from);
430	    }
431	
432	    private static ClerkLimit clerkLimit(String requested, LocalDate from) throws InvalidSettingException {
433	        if (requested == null) {
434	            return new ClerkLimit(false, null, null);
435	        }
436	        String value = requested.trim();
437	        if (value.isEmpty()) {
438	            return new ClerkLimit(true, null, from);
439	        }
440	        if (!AMOUNT.matcher(value).matches()) {
441	            throw new InvalidSettingException("The clerk limit must be 0.00 or more, with at most two decimals, or blank.");
442	        }
443	        return new ClerkLimit(true, new BigDecimal(value).setScale(2), from);
444	    }
