package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import net.officefloor.hq.app.claim.LateCharge;

/**
 * A sheet's dated settings: for each key (floor, late-pct, terms, terms-&lt;grade&gt;, clerk-limit, cap, proof-threshold) the values
 * recorded, by from-date (a value null: blank). The value in force on a date is the one with the latest from-date on or
 * before it; before every from-date it is the sheet's starting value (floor 1.00, late percent 0.00, terms 14; none
 * for the clerk limit, the cap, the proof threshold and a grade's own terms).
 */
public record DatedSettings(Map<String, NavigableMap<LocalDate, String>> values) {

    public static final String FLOOR = "floor";
    public static final String LATE_PCT = "late-pct";
    public static final String TERMS = "terms";
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The key of a grade's own terms. */
    public static String gradeTerms(String grade) {
        return TERMS + "-" + grade;
    }

    /** The audit field for a from-date typed with a save, " from=<date>", or "" when none was typed (the sheet's today). */
    public static String auditFrom(LocalDate from) {
        return from == null ? "" : " from=" + from;
    }

    /** The date a value saved with this from-date (null: none typed) is recorded from: it, else the sheet's today. */
    public static LocalDate fromOr(LocalDate from, LocalDate today) {
        return from == null ? today : from;
    }

    /** One value recorded from a date. */
    public record FromValue(LocalDate from, String value) {
    }

    /** The value of the key in force on the date (null: blank, or nothing recorded on or before it). */
    private String on(String key, LocalDate date) {
        NavigableMap<LocalDate, String> recorded = values.get(key);
        if (recorded == null || date == null) {
            return null;
        }
        Map.Entry<LocalDate, String> entry = recorded.floorEntry(date);
        return entry == null ? null : entry.getValue();
    }

    /** The floor in force on the date. */
    public BigDecimal floorOn(LocalDate date) {
        String value = on(FLOOR, date);
        return value == null ? SettingRepository.DEFAULT_FLOOR : new BigDecimal(value).setScale(2);
    }

    /** The late percent in force on the date. */
    public BigDecimal latePctOn(LocalDate date) {
        String value = on(LATE_PCT, date);
        return value == null ? SettingRepository.DEFAULT_LATE_PCT : new BigDecimal(value).setScale(2);
    }

    /** What an overdue claim is charged on the given today: the late percent in force on each 30-day boundary. */
    public LateCharge lateCharge(LocalDate today) {
        return new LateCharge(this::latePctOn, today);
    }

    /** The sheet's terms in days in force on the date. */
    public int termsOn(LocalDate date) {
        String value = on(TERMS, date);
        return value == null ? SettingRepository.DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** The grade's own terms in force on the date (null: none, the sheet's terms). */
    public Integer gradeTermsOn(String grade, LocalDate date) {
        String value = on(gradeTerms(grade), date);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The terms in days for a claim of the grade dated on the date: the grade's own in force then, else the sheet's. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }

    /** The grades' own terms in force on the date, by grade (a grade with none left out). */
    public Map<String, Integer> gradeTermsOn(LocalDate date) {
        Map<String, Integer> terms = new LinkedHashMap<>();
        values.keySet().stream().filter((k) -> k.startsWith(TERMS + "-")).sorted().forEach((key) -> {
            String grade = key.substring(TERMS.length() + 1);
            Integer own = gradeTermsOn(grade, date);
            if (own != null) {
                terms.put(grade, own);
            }
        });
        return terms;
    }

    /** The clerk limit in force on the date (null: no limit). */
    public BigDecimal clerkLimitOn(LocalDate date) {
        String value = on(CLERK_LIMIT, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The cap in force on the date (null: no cap). */
    public BigDecimal capOn(LocalDate date) {
        String value = on(CAP, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The proof threshold in force on the date (null: none). */
    public BigDecimal proofThresholdOn(LocalDate date) {
        String value = on(PROOF_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /**
     * Whether a claim of the date with this due (null: n/a) needs a proof to be settled or approved: its due is above
     * the proof threshold in force on its date.
     */
    public boolean needsProof(LocalDate date, BigDecimal due) {
        BigDecimal threshold = proofThresholdOn(date);
        return threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** Every value recorded, by key, oldest from-date first. */
    public Map<String, List<FromValue>> history() {
        Map<String, List<FromValue>> history = new LinkedHashMap<>();
        values.forEach((key, recorded) -> history.put(key,
                recorded.entrySet().stream().map((e) -> new FromValue(e.getKey(), e.getValue())).toList()));
        return history;
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated proof threshold with two decimals; {@code value} null: none. {@code given} false: left as it is. {@code from} null: none typed, the sheet's today. */
public record ProofThreshold(boolean given, BigDecimal value, LocalDate from) {
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class SaveProofThreshold {
    public void save(@Val ProofThreshold threshold, @Val Sheet sheet, SettingRepository repository) {
        if (threshold.given()) {
            repository.saveDated(sheet.id(), DatedSettings.PROOF_THRESHOLD,
                    DatedSettings.fromOr(threshold.from(), sheet.today()),
                    threshold.value() == null ? null : threshold.value().toPlainString());
        }
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the proof threshold just saved (blank: none), even when it is the one the sheet had; nothing when it was left as it is. */
public class AuditProofThreshold {
    public void audit(@Val ProofThreshold threshold, @Val Sheet sheet, @RequestParam("user") String user, Audit audit) {
        if (!threshold.given()) {
            return;
        }
        audit.record("SETTING_CHANGED sheet=" + sheet.id() + " by=" + user + " key=proof-threshold value="
                + (threshold.value() == null ? "" : threshold.value().toPlainString())
                + DatedSettings.auditFrom(threshold.from()));
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.constraints.Size;
import java.util.Map;

/**
 * The settings as the form submits them; a setting left out (null) is left as it is. The clerk limit has two
 * decimals at most (blank: no limit); the floor has two decimals at most (blank: back to 1.00); the terms are
 * whole days, 0 or more (blank: back to 14); the late percent has two decimals at most (blank: back to 0.00); the policy date is
 * yyyy-MM-dd (blank: the sheet's today); the period numbering from date is yyyy-MM-dd (blank: off); the cap has two decimals at most (blank: no cap); the proof threshold has two decimals at most (blank: none). The grade terms are
 * whole days, 0 or more, by grade, each only for a grade it carries (blank: none of its own, the sheet's terms).
 * The clerk limit, floor, terms, late percent, cap, proof threshold and each grade's terms are recorded from their from-date, yyyy-MM-dd
 * (left out or blank: the sheet's today). The permissions are, by action (open, settle, void, reassign, close, reopen),
 * the roles allowed it, comma separated (blank: the standing rule); they are not dated. The grace days are whole days,
 * 0 or more (blank: off); they are not dated.
 */
public record SettingsRequest(@Size(max = 30) String clerkLimit, @Size(max = 30) String floor, @Size(max = 30) String terms,
        @Size(max = 30) String latePct, @Size(max = 30) String policyDate, @Size(max = 30) String periodNumberingFrom, @Size(max = 30) String cap,
        @Size(max = 30) String proofThreshold,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeTerms,
        @Size(max = 30) String clerkLimitFrom, @Size(max = 30) String floorFrom, @Size(max = 30) String termsFrom,
        @Size(max = 30) String latePctFrom, @Size(max = 30) String capFrom, @Size(max = 30) String proofThresholdFrom,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeTermsFrom,
        @Size(max = 10) Map<String, @Size(max = 100) String> permissions, @Size(max = 30) String graceDays) {
}
package net.officefloor.hq.app.setting;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The settings as the screen reads them: the clerk limit (null: no limit), the floor, the terms in days, the terms set for
 * each grade that has its own (by grade), the late percent, the policy date ("": blank, the sheet's today), the period
 * numbering from date ("": off), the cap ("": none), the proof threshold ("": none) — the dated ones as in force on the sheet's today — each role given,
 * by user name, the permission matrix (by action, the roles allowed it; "": blank, the standing rule), and every dated value recorded, by key, oldest from-date first (value "": blank), the grace days ("": off) and the steward role delegated, in the order made.
 */
public record SettingsResponse(String clerkLimit, String floor, int terms, Map<String, Integer> gradeTerms, String latePct, String policyDate, String periodNumberingFrom, String cap, String proofThreshold, List<RoleResponse> roles,
        Map<String, List<FromValueResponse>> history, Map<String, String> permissions, String graceDays,
        List<DelegationResponse> delegations) {

    public record RoleResponse(String user, String role) {
    }

    public record DelegationResponse(String user, String from, String to, String by) {
    }

    public record FromValueResponse(String from, String value) {
    }

    public static SettingsResponse from(Settings settings) {
        Map<String, List<FromValueResponse>> history = new LinkedHashMap<>();
        settings.dated().history().forEach((key, values) -> history.put(key, values.stream()
                .map((v) -> new FromValueResponse(v.from().toString(), v.value() == null ? "" : v.value())).toList()));
        return new SettingsResponse(
                settings.clerkLimit() == null ? null : settings.clerkLimit().toPlainString(),
                settings.floor().toPlainString(),
                settings.terms(),
                settings.gradeTerms(),
                settings.latePct().toPlainString(),
                settings.policyDate() == null ? "" : settings.policyDate().toString(),
                settings.periodNumberingFrom() == null ? "" : settings.periodNumberingFrom().toString(),
                settings.cap() == null ? "" : settings.cap().toPlainString(),
                settings.proofThreshold() == null ? "" : settings.proofThreshold().toPlainString(),
                settings.roles().stream().map((r) -> new RoleResponse(r.user(), r.role().label())).toList(),
                history,
                settings.permissions().entries(),
                settings.graceDays() == null ? "" : settings.graceDays().toString(),
                settings.delegations().stream().map((d) -> new DelegationResponse(d.user(), d.from().toString(),
                        d.to().toString(), d.by())).toList());
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;

/**
 * A sheet's settings: its clerk limit (null: no limit), its floor (a claim's live due is at least it), its terms
 * (a claim is due by its date plus this many days), the terms set for each grade that has its own (by grade; any
 * other grade uses the sheet's terms), its late percent (an overdue claim gains it of its figure
 * every full 30 days), its rounding policy date (null: blank, the sheet's
 * today), its period numbering from date (null: off; on or after it, an opened claim is numbered within its period)
 * its cap (null: none; a person's due-total is at most it), its proof threshold (null: none; a claim whose due is above
 * the one in force on its date is settled or approved only once it has a proof) the roles given to user names (any other name is a clerk) and its
 * permission matrix (the roles allowed each of open, settle, void, reassign, close and reopen) and its grace days (null: off;
 * when its today is changed, an open period whose to-date plus them is before the new today is closed).
 * The clerk limit, floor, terms, grade terms, late percent, cap and proof threshold are those in force on the sheet's today; {@code dated}
 * holds every value recorded for them, by from-date. {@code delegations} are the steward role delegated to user names, in the
 * order made; one in force on {@code today} (the sheet's today) makes its user act as a steward in every rule.
 */
public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms, Map<String, Integer> gradeTerms, BigDecimal latePct,
        LocalDate policyDate, LocalDate periodNumberingFrom, BigDecimal cap, BigDecimal proofThreshold, List<UserRole> roles, DatedSettings dated, Permissions permissions, Integer graceDays,
        LocalDate today, List<Delegation> delegations) {

    /** The role the user name acts in: steward while a delegation to it is in force on today, else its given role. */
    public Role roleOf(String user) {
        return delegatorOf(user) != null ? Role.STEWARD : givenRoleOf(user);
    }

    /** The role given to the user name, else clerk (a delegation aside). */
    public Role givenRoleOf(String user) {
        return roles.stream().filter((r) -> r.user().equals(user)).map(UserRole::role).findFirst().orElse(Role.CLERK);
    }

    /** The steward who delegated the role to the user name by the latest delegation in force on today, else null. */
    public String delegatorOf(String user) {
        String by = null;
        for (Delegation d : delegations) {
            if (d.user().equals(user) && d.covers(today)) {
                by = d.by();
            }
        }
        return by;
    }

    /** Whether the user's role is allowed the action (open, settle, void, reassign, close or reopen) by the permission matrix. */
    public boolean may(String user, String action) {
        return permissions.allows(action, roleOf(user));
    }

    /** Whether the user may settle a claim with this due (null: n/a, within any limit). */
    public boolean maySettle(String user, BigDecimal due) {
        return roleOf(user) == Role.STEWARD || clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSettingsRequest {

    /** 0.00 or more, with at most two decimals. */
    private static final Pattern AMOUNT = Pattern.compile("\\d{1,13}(\\.\\d{1,2})?|\\.\\d{1,2}");

    /** A percent: 0.00 or more, with at most two decimals. */
    private static final Pattern PERCENT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?|\\.\\d{1,2}");

    /** The grades terms can be set for. */
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** 0 or more whole days. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    public void validate(@RequestBody @Valid SettingsRequest request, Out<ClerkLimit> limit, Out<Floor> floor,
            Out<Terms> terms, Out<LatePct> latePct, Out<PolicyDate> policyDate,
            Out<PeriodNumberingFrom> periodNumberingFrom, Out<GradeTerms> gradeTerms, Out<Cap> cap,
            Out<ProofThreshold> proofThreshold, Out<PermissionChanges> permissions, Out<GraceDays> graceDays)
            throws InvalidSettingException {
        limit.set(clerkLimit(request.clerkLimit(), from(request.clerkLimitFrom(), "clerk limit")));
        floor.set(floor(request.floor(), from(request.floorFrom(), "floor")));
        terms.set(terms(request.terms(), from(request.termsFrom(), "terms")));
        latePct.set(latePct(request.latePct(), from(request.latePctFrom(), "late percent")));
        policyDate.set(policyDate(request.policyDate()));
        periodNumberingFrom.set(periodNumberingFrom(request.periodNumberingFrom()));
        gradeTerms.set(gradeTerms(request.gradeTerms(), request.gradeTermsFrom()));
        cap.set(cap(request.cap(), from(request.capFrom(), "cap")));
        proofThreshold.set(proofThreshold(request.proofThreshold(), from(request.proofThresholdFrom(), "proof threshold")));
        permissions.set(permissions(request.permissions()));
        graceDays.set(graceDays(request.graceDays()));
    }

    /** A from-date typed with a setting (null: left out or blank, the sheet's today). */
    private static LocalDate from(String requested, String what) throws InvalidSettingException {
        String value = requested == null ? "" : requested.trim();
        if (value.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(value);
        } catch (DateTimeParseException e) {
            throw new InvalidSettingException("The " + what + " from-date must be a date (yyyy-MM-dd), or blank.");
        }
    }

    private static PermissionChanges permissions(Map<String, String> requested) throws InvalidSettingException {
        Map<String, String> entries = new LinkedHashMap<>();
        if (requested == null) {
            return new PermissionChanges(entries);
        }
        for (String action : requested.keySet()) {
            if (!Permissions.ACTIONS.contains(action)) {
                throw new InvalidSettingException("Permissions can only be set for open, settle, void, reassign, close or reopen.");
            }
        }
        for (String action : Permissions.ACTIONS) {
            if (!requested.containsKey(action)) {
                continue;
            }
            String value = requested.get(action) == null ? "" : requested.get(action).trim();
            if (value.isEmpty()) {
                entries.put(action, "");
            } else if (Permissions.parse(value) == null) {
                throw new InvalidSettingException("The roles for " + action + " must be clerk or steward, comma separated, or blank.");
            } else {
                entries.put(action, Permissions.label(value));
            }
        }
        return new PermissionChanges(entries);
    }

    private static GraceDays graceDays(String requested) throws InvalidSettingException {
        if (requested == null) {
            return new GraceDays(false, null);
        }
        String value = requested.trim();
        if (value.isEmpty()) {
            return new GraceDays(true, null);
        }
        if (!DAYS.matcher(value).matches()) {
            throw new InvalidSettingException("The grace days must be a whole number of days, 0 or more, or blank.");
        }
        return new GraceDays(true, Integer.parseInt(value));
    }

    private static Cap cap(String requested, LocalDate from) throws InvalidSettingException {
        if (requested == null) {
            return new Cap(false, null, null);
        }
        String value = requested.trim();
        if (value.isEmpty()) {
            return new Cap(true, null, from);
        }
        if (!AMOUNT.matcher(value).matches()) {
            throw new InvalidSettingException("The cap must be 0.00 or more, with at most two decimals, or blank.");
        }
        return new Cap(true, new BigDecimal(value).setScale(2), from);
    }

    private static ProofThreshold proofThreshold(String requested, LocalDate from) throws InvalidSettingException {
        if (requested == null) {
            return new ProofThreshold(false, null, null);
        }
        String value = requested.trim();
        if (value.isEmpty()) {
            return new ProofThreshold(true, null, from);
        }
        if (!AMOUNT.matcher(value).matches()) {
            throw new InvalidSettingException("The proof threshold must be 0.00 or more, with at most two decimals, or blank.");
        }
        return new ProofThreshold(true, new BigDecimal(value).setScale(2), from);
    }

    private static ClerkLimit clerkLimit(String requested, LocalDate from) throws InvalidSettingException {
        if (requested == null) {
            return new ClerkLimit(false, null, null);
        }
        String value = requested.trim();
        if (value.isEmpty()) {
            return new ClerkLimit(true, null, from);
        }
        if (!AMOUNT.matcher(value).matches()) {
            throw new InvalidSettingException("The clerk limit must be 0.00 or more, with at most two decimals, or blank.");
        }
        return new ClerkLimit(true, new BigDecimal(value).setScale(2), from);
    }

package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.sql.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Rounding;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingRepository {

    /** The floor a sheet starts with. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms a sheet starts with, in days. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent a sheet starts with. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings: the dated ones in force on its today (and every value recorded), its policy date, its period numbering from date and its roles, by user name. */
    public Settings find(String sheetId) {
        List<UserRole> roles = jdbc.query("SELECT sheet_id, user_name, role FROM user_role WHERE sheet_id = ?"
                + " ORDER BY user_name", (rs, n) -> new UserRole(rs.getString("sheet_id"), rs.getString("user_name"),
                        Role.valueOf(rs.getString("role"))), sheetId);
        List<Date> found = jdbc.query("SELECT today FROM sheet WHERE id = ?", (rs, n) -> rs.getDate("today"), sheetId);
        LocalDate today = found.isEmpty() || found.get(0) == null ? LocalDate.now() : found.get(0).toLocalDate();
        DatedSettings dated = dated(sheetId);
        return new Settings(sheetId, dated.clerkLimitOn(today), dated.floorOn(today), dated.termsOn(today),
                dated.gradeTermsOn(today), dated.latePctOn(today), policyDate(sheetId), periodNumberingFrom(sheetId),
                dated.capOn(today), dated.proofThresholdOn(today), roles, dated, permissions(sheetId), graceDays(sheetId),
                today, delegations(sheetId));
    }

    /** The sheet's dated settings: every value recorded, by key and from-date. */
    public DatedSettings dated(String sheetId) {
        Map<String, NavigableMap<LocalDate, String>> values = new LinkedHashMap<>();
        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_from WHERE sheet_id = ?"
                + " ORDER BY setting_key, from_date", (rs) -> {
                    values.computeIfAbsent(rs.getString("setting_key"), (k) -> new TreeMap<>())
                            .put(rs.getDate("from_date").toLocalDate(), rs.getString("setting_value"));
                }, sheetId);
        return new DatedSettings(values);
    }

    /** Record the key's value from the date (null: blank), replacing any value already recorded from that date. */
    public void saveDated(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("DELETE FROM setting_from WHERE sheet_id = ? AND setting_key = ? AND from_date = ?",
                sheetId, key, Date.valueOf(from));
        jdbc.update("INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value) VALUES (?, ?, ?, ?)",
                sheetId, key, Date.valueOf(from), value);
    }

    /** The sheet's rounding policy date as set (null: blank, the sheet's today). */
    public LocalDate policyDate(String sheetId) {
        List<Date> date = jdbc.query("SELECT policy_date FROM sheet WHERE id = ?",
                (rs, n) -> rs.getDate("policy_date"), sheetId);
        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
    }

    /** How the sheet rounds the given claims' live figures on the given today: by its policy date (blank: today). */
    public Rounding rounding(String sheetId, LocalDate today, List<Claim> claims) {
        LocalDate policyDate = policyDate(sheetId);
        return Rounding.of(policyDate == null ? today : policyDate, claims);
    }

    /** Set the sheet's rounding policy date (null: blank, the sheet's today). */
    public void savePolicyDate(String sheetId, LocalDate policyDate) {
        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", policyDate == null ? null : Date.valueOf(policyDate), sheetId);
    }

    /** The sheet's period numbering from date (null: blank, off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        List<Date> date = jdbc.query("SELECT period_numbering_from FROM sheet WHERE id = ?",
                (rs, n) -> rs.getDate("period_numbering_from"), sheetId);
        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
    }

    /** Set the sheet's period numbering from date (null: blank, off). */
    public void savePeriodNumberingFrom(String sheetId, LocalDate from) {
        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", from == null ? null : Date.valueOf(from), sheetId);
    }

    /** The sheet's grace days (null: blank, off). */
    public Integer graceDays(String sheetId) {
        List<Integer> days = jdbc.query("SELECT grace_days FROM sheet WHERE id = ?",
                (rs, n) -> (Integer) rs.getObject("grace_days", Integer.class), sheetId);
        return days.isEmpty() ? null : days.get(0);
    }

    /** Set the sheet's grace days (null: blank, off). */
    public void saveGraceDays(String sheetId, Integer days) {
        jdbc.update("UPDATE sheet SET grace_days = ? WHERE id = ?", days, sheetId);
    }

    /** The sheet's permission matrix: the roles set for each action, as shown (an action with none keeps the standing rule). */
    public Permissions permissions(String sheetId) {
        Map<String, String> set = new LinkedHashMap<>();
        jdbc.query("SELECT action, roles FROM permission WHERE sheet_id = ?", (rs) -> {
            set.put(rs.getString("action"), rs.getString("roles"));
        }, sheetId);
        return new Permissions(set);
    }

    /** Set the roles allowed the action on the sheet ("": blank, back to the standing rule). */
    public void savePermission(String sheetId, String action, String roles) {
        jdbc.update("DELETE FROM permission WHERE sheet_id = ? AND action = ?", sheetId, action);
        if (!roles.isEmpty()) {
            jdbc.update("INSERT INTO permission (sheet_id, action, roles) VALUES (?, ?, ?)", sheetId, action, roles);
        }
    }

    /** The steward role delegated on the sheet, in the order made. */
    public List<Delegation> delegations(String sheetId) {
        return jdbc.query("SELECT sheet_id, user_name, from_date, to_date, by_user FROM delegation WHERE sheet_id = ?"
                + " ORDER BY id", (rs, n) -> new Delegation(rs.getString("sheet_id"), rs.getString("user_name"),
                        rs.getDate("from_date").toLocalDate(), rs.getDate("to_date").toLocalDate(), rs.getString("by_user")),
                sheetId);
    }

    /** The steward who delegated the role to the user name by the latest delegation in force on the sheet's today, else null. */
    public String delegatorOf(String sheetId, String user) {
        List<String> found = jdbc.query("SELECT d.by_user FROM delegation d JOIN sheet s ON s.id = d.sheet_id"
                + " WHERE d.sheet_id = ? AND d.user_name = ? AND s.today BETWEEN d.from_date AND d.to_date"
                + " ORDER BY d.id DESC LIMIT 1", (rs, n) -> rs.getString("by_user"), sheetId, user);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Record the steward role delegated. */
    public void saveDelegation(Delegation delegation) {
        jdbc.update("INSERT INTO delegation (sheet_id, user_name, from_date, to_date, by_user) VALUES (?, ?, ?, ?, ?)",
                delegation.sheetId(), delegation.user(), Date.valueOf(delegation.from()), Date.valueOf(delegation.to()),
                delegation.by());
    }

    /** Give the user name its role on the sheet, replacing any it had. */
    public void saveRole(UserRole role) {
        int updated = jdbc.update("UPDATE user_role SET role = ? WHERE sheet_id = ? AND user_name = ?",
                role.role().name(), role.sheetId(), role.user());
        if (updated == 0) {
            jdbc.update("INSERT INTO user_role (sheet_id, user_name, role) VALUES (?, ?, ?)",
                    role.sheetId(), role.user(), role.role().name());
        }
    }
}
# Set the sheet's clerk limit (blank: no limit), its floor (blank: 1.00) and its terms in days (blank: 14) and each grade's own terms in days (blank: none, the sheet's terms) and its late percent (blank: 0.00) and its policy date (blank: the sheet's today) and its period numbering from date (blank: off) and its cap (blank: none) and its proof threshold (blank: none) and its permission matrix (by action, the roles allowed it, comma separated; blank: the standing rule) and its grace days (blank: off), each only when the request carries it;
# a value that is negative or has more than two decimals (terms: not whole days) is refused (400). A floor, late percent, policy date or cap moves the dues (terms do not: a claim's due-by is fixed when it is created), so the
# figures it moved are recorded after it.
