23	
24	/** The settings the form sends: only those whose field was touched since the last save. */
25	type SettingsInput = {
26	  clerkLimit?: string;
27	  floor?: string;
28	  terms?: string;
29	  gradeTerms?: Record<string, string>;
30	  latePct?: string;
31	  policyDate?: string;
32	  periodNumberingFrom?: string;
33	  cap?: string;
34	  proofThreshold?: string;
35	  clerkLimitFrom?: string;
36	  floorFrom?: string;
37	  termsFrom?: string;
38	  latePctFrom?: string;
39	  capFrom?: string;
40	  proofThresholdFrom?: string;
41	  gradeTermsFrom?: Record<string, string>;
42	  permissions?: Record<string, string>;
43	  graceDays?: string;
44	};
45	
46	/** The from-date field of each dated setting, by its key as the screen names it (terms-A for a grade's terms). */
47	type Froms = Record<string, string>;
48	
49	type Touched = {
50	  clerkLimit: boolean;
51	  floor: boolean;
52	  terms: boolean;
53	  latePct: boolean;
54	  policyDate: boolean;
55	  periodNumberingFrom: boolean;
56	  cap: boolean;
57	  proofThreshold: boolean;
58	  graceDays: boolean;
59	};
60	
61	const UNTOUCHED: Touched = {
62	  clerkLimit: false,
63	  floor: false,
64	  terms: false,
65	  latePct: false,
66	  policyDate: false,
67	  periodNumberingFrom: false,
68	  cap: false,
69	  proofThreshold: false,
70	  graceDays: false,
71	};
72	
73	// The sheet's clerk limit (blank: no limit), floor, terms, each grade's terms (blank: the sheet's), late percent and policy date (blank: today) and period numbering from date (blank: off) and cap (blank: none) and proof threshold (blank: none) in force, and the
74	// permission matrix (by action, the roles allowed it; blank: the standing rule; not dated), and the grace days (blank: off; not dated), and the form that sets them. Saving sends
75	// only the fields touched since the last save, so a blank field left alone changes nothing. A dated setting (the clerk
76	// limit, floor, terms, each grade's terms, late percent, cap and proof threshold) is recorded from the date typed beside it (blank: the
77	// sheet's today); the value shown is the one in force on the sheet's today.
78	export function SettingsForm() {
79	  const [user] = useCurrentUser();
80	  const [sheet] = useCurrentSheet();
81	  const settings = useSettings().data;
82	  const [clerkLimit, setClerkLimit] = useState('');
83	  const [floor, setFloor] = useState('');
84	  const [terms, setTerms] = useState('');
85	  const [gradeTerms, setGradeTerms] = useState<Record<string, string>>({});
86	  const [touchedGrades, setTouchedGrades] = useState<Record<string, boolean>>({});
87	  const [latePct, setLatePct] = useState('');
88	  const [policyDate, setPolicyDate] = useState('');
89	  const [periodNumberingFrom, setPeriodNumberingFrom] = useState('');
90	  const [cap, setCap] = useState('');
91	  const [proofThreshold, setProofThreshold] = useState('');
92	  const [graceDays, setGraceDays] = useState('');
93	  const [perms, setPerms] = useState<Record<string, string>>({});
94	  const [touchedPerms, setTouchedPerms] = useState<Record<string, boolean>>({});
95	  const [froms, setFroms] = useState<Froms>({});
96	  const [touched, setTouched] = useState<Touched>(UNTOUCHED);
97	  const [error, setError] = useState('');
98	  const queryClient = useQueryClient();
99	  const once = useOneAtATime();
100	
101	  const save = useMutation({
102	    mutationFn: (input: SettingsInput) =>
103	      putJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings?user=${encodeURIComponent(user)}`, input),
104	    onSuccess: async (saved) => {
105	      setClerkLimit('');
106	      setFloor('');
107	      setTerms('');
108	      setGradeTerms({});
109	      setTouchedGrades({});
110	      setLatePct('');
111	      setPolicyDate('');
112	      setPeriodNumberingFrom('');
113	      setCap('');
114	      setProofThreshold('');
115	      setGraceDays('');
116	      setPerms({});
117	      setTouchedPerms({});
118	      setFroms({});
119	      setTouched(UNTOUCHED);
120	      setError('');
121	      queryClient.setQueryData(settingsKey(sheet), saved);
122	      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet) });
123	    },
124	    onError: () => setError('That setting could not be saved.'),
125	  });
126	
127	  if (!user || !sheet) return null;
128	
129	  // The from-date typed for a dated setting: '' (the sheet's today), a date, or null when it is not a date.
130	  const fromOf = (key: string): string | null => {
131	    const value = (froms[key] ?? '').trim();
132	    return value === '' || DATE.test(value) ? value : null;
133	  };
134	
135	  // The from-date field beside a dated setting's field.
136	  const fromField = (key: string, label: string) => (
137	    <input
138	      data-testid={`setting-${key}-from`}
139	      placeholder={`${label} from, yyyy-MM-dd (blank: the sheet's today)`}
140	      value={froms[key] ?? ''}
141	      onChange={(e) => {
142	        const value = e.target.value;
143	        setFroms((f) => ({ ...f, [key]: value }));
144	        setError('');
145	      }}
146	    />
147	  );
148	
149	  const submit = (e: FormEvent) => {
150	    e.preventDefault();
151	    setError('');
152	    const input: SettingsInput = {};
153	    for (const [key, label] of [
154	      ['clerk-limit', 'clerk limit'],
155	      ['floor', 'floor'],
156	      ['terms', 'terms'],
157	      ...GRADES.map((g) => [`terms-${g}`, `terms for grade ${g}`]),
158	      ['late-pct', 'late percent'],
159	      ['cap', 'cap'],
160	      ['proof-threshold', 'proof threshold'],
161	    ]) {
162	      if (fromOf(key) === null) {
163	        setError(`Type the ${label} from-date as yyyy-MM-dd, or leave it blank for the sheet's today.`);
164	        return;
165	      }
166	    }
167	    const datedFrom = (key: string) => fromOf(key) || undefined;
168	    if (touched.clerkLimit) {
169	      const value = clerkLimit.trim();
170	      if (value !== '' && !AMOUNT.test(value)) {
171	        setError('Type a clerk limit of 0.00 or more, with at most two decimals, or leave it blank for no limit.');
172	        return;
173	      }
174	      input.clerkLimit = value;
175	      input.clerkLimitFrom = datedFrom('clerk-limit');
176	    }
177	    if (touched.floor) {
178	      const value = floor.trim();
179	      if (value !== '' && !AMOUNT.test(value)) {
180	        setError(`Type a floor of 0.00 or more, with at most two decimals, or leave it blank for ${DEFAULT_FLOOR}.`);
181	        return;
182	      }
183	      input.floor = value;
184	      input.floorFrom = datedFrom('floor');
185	    }
186	    if (touched.terms) {
187	      const value = terms.trim();
188	      if (value !== '' && !DAYS.test(value)) {
189	        setError(`Type terms of 0 or more whole days, or leave them blank for ${DEFAULT_TERMS}.`);
190	        return;
191	      }
192	      input.terms = value;
193	      input.termsFrom = datedFrom('terms');
194	    }
195	    for (const g of GRADES) {
196	      if (!touchedGrades[g]) continue;
197	      const value = (gradeTerms[g] ?? '').trim();
198	      if (value !== '' && !DAYS.test(value)) {
199	        setError(`Type terms for grade ${g} of 0 or more whole days, or leave them blank for the sheet's terms.`);
200	        return;
201	      }
202	      input.gradeTerms = { ...input.gradeTerms, [g]: value };
203	      const from = datedFrom(`terms-${g}`);
204	      if (from) input.gradeTermsFrom = { ...input.gradeTermsFrom, [g]: from };
205	    }
206	    if (touched.latePct) {
207	      const value = latePct.trim();
208	      if (value !== '' && !PERCENT.test(value)) {
209	        setError(
210	          `Type a late percent of 0.00 or more, with at most two decimals, or leave it blank for ${DEFAULT_LATE_PCT}.`,
211	        );
212	        return;
213	      }
214	      input.latePct = value;
215	      input.latePctFrom = datedFrom('late-pct');
216	    }
217	    if (touched.policyDate) {
218	      const value = policyDate.trim();
219	      if (value !== '' && !DATE.test(value)) {
220	        setError("Type a policy date as yyyy-MM-dd, or leave it blank for the sheet's today.");
221	        return;
222	      }
223	      input.policyDate = value;
224	    }
225	    if (touched.periodNumberingFrom) {
226	      const value = periodNumberingFrom.trim();
227	      if (value !== '' && !DATE.test(value)) {
228	        setError('Type a period numbering from date as yyyy-MM-dd, or leave it blank for off.');
229	        return;
230	      }
231	      input.periodNumberingFrom = value;
232	    }
233	    if (touched.cap) {
234	      const value = cap.trim();
235	      if (value !== '' && !AMOUNT.test(value)) {
236	        setError('Type a cap of 0.00 or more, with at most two decimals, or leave it blank for none.');
237	        return;
238	      }
239	      input.cap = value;
240	      input.capFrom = datedFrom('cap');
241	    }
242	    if (touched.proofThreshold) {
243	      const value = proofThreshold.trim();
244	      if (value !== '' && !AMOUNT.test(value)) {
245	        setError('Type a proof threshold of 0.00 or more, with at most two decimals, or leave it blank for none.');
246	        return;
247	      }
248	      input.proofThreshold = value;
249	      input.proofThresholdFrom = datedFrom('proof-threshold');
250	    }
251	    if (touched.graceDays) {
252	      const value = graceDays.trim();
253	      if (value !== '' && !DAYS.test(value)) {
254	        setError('Type grace days of 0 or more whole days, or leave them blank for off.');
255	        return;
256	      }
257	      input.graceDays = value;
258	    }
259	    for (const a of PERMISSION_ACTIONS) {
260	      if (!touchedPerms[a]) continue;
261	      const value = (perms[a] ?? '').trim();
262	      if (value !== '' && !ROLE_LIST.test(value)) {
263	        setError(`Type the roles allowed to ${a} as clerk or steward, comma separated, or leave it blank for the standing rule.`);
264	        return;
265	      }
266	      input.permissions = { ...input.permissions, [a]: value };
267	    }
268	    if (
269	      input.clerkLimit === undefined &&
270	      input.floor === undefined &&
271	      input.terms === undefined &&
272	      input.gradeTerms === undefined &&
273	      input.latePct === undefined &&
274	      input.policyDate === undefined &&
275	      input.periodNumberingFrom === undefined &&
276	      input.cap === undefined &&
277	      input.proofThreshold === undefined &&
278	      input.permissions === undefined &&
279	      input.graceDays === undefined
280	    )
281	      return;
282	    once(() => save.mutateAsync(input));
283	  };
284	
285	  return (
286	    <section data-testid="settings">
287	      <p>
288	        Clerk limit: <span data-testid="setting-clerk-limit-current">{settings?.clerkLimit ?? ''}</span>
289	      </p>
290	      <p>
291	        Floor: <span data-testid="setting-floor-current">{settings?.floor ?? ''}</span>
292	      </p>
293	      <p>
294	        Terms (days): <span data-testid="setting-terms-current">{settings?.terms ?? ''}</span>
295	      </p>
296	      {GRADES.map((g) => (
297	        <p key={g}>
298	          Terms for grade {g} (days):{' '}
299	          <span data-testid={`setting-terms-${g}-current`}>
300	            {settings ? (settings.gradeTerms[g] ?? settings.terms) : ''}
301	          </span>
302	        </p>
303	      ))}
304	      <p>
305	        Late percent: <span data-testid="setting-late-pct-current">{settings?.latePct ?? ''}</span>
306	      </p>
307	      <p>
308	        Policy date: <span data-testid="setting-policy-date-current">{settings?.policyDate ?? ''}</span>
309	      </p>
310	      <p>
311	        Period numbering from:{' '}
312	        <span data-testid="setting-period-numbering-from-current">{settings?.periodNumberingFrom ?? ''}</span>
313	      </p>
314	      <p>
315	        Cap: <span data-testid="setting-cap-current">{settings?.cap ?? ''}</span>
316	      </p>
